import {ENGINE_VERSION} from './engine.mjs';
import {graphStats} from './main-paths.mjs';

// Shared by the original page and the framework-independent adapter.
export function serializeNetwork(result,smoothed,context,includeInference=true){
 const {width,height,originalWidth,originalHeight,name,roi,parameters,manualEdits=0}=context;
 const sx=originalWidth/width,sy=originalHeight/height,round=v=>Math.round(v*1000)/1000,map=p=>[round(p[0]*sx),round(p[1]*sy)];
 const scaledLength=graph=>graph.edges.reduce((sum,e)=>sum+e.points.slice(1).reduce((s,p,i)=>s+Math.hypot((p[0]-e.points[i][0])*sx,(p[1]-e.points[i][1])*sy),0),0);
 const selectedInference=new Uint8Array(width*height);for(const e of smoothed.edges)for(let i=1;i<e.rawPoints.length;i++)if(e.inferredSegments[i-1])for(const [x,y]of [e.rawPoints[i-1],e.rawPoints[i]])selectedInference[Math.floor(y)*width+Math.floor(x)]=1;
 const supportsSelected=bridge=>bridge.points.some(([x,y])=>{for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){const xx=Math.floor(x)+dx,yy=Math.floor(y)+dy;if(xx>=0&&yy>=0&&xx<width&&yy<height&&selectedInference[yy*width+xx])return true;}return false;});
 const bridges=result.bridges.filter(supportsSelected).map(b=>{const originallyInferred=b.points.filter(([x,y])=>!result.directMask[Math.floor(y)*width+Math.floor(x)]);const retained=originallyInferred.filter(([x,y])=>result.inferredMask[Math.floor(y)*width+Math.floor(x)]);return {...b,points:b.points.map(map),retainedFraction:originallyInferred.length?retained.length/originallyInferred.length:0,evidence:{...b.evidence,pixelMetricSpace:'processing-image',scoreIsProbability:false}};}).filter(b=>b.retainedFraction>0);
 return {schemaVersion:'2.5',engine:'formic-classical-geodesic',engineVersion:ENGINE_VERSION,createdAt:new Date().toISOString(),image:{name:name,width:originalWidth,height:originalHeight},processing:{width:width,height:height,scaleToOriginal:{x:sx,y:sy},roi:{...roi},parameters:{...parameters},manualEdits:manualEdits,surfaceDetection:result.surfaceDiagnostics,pathSmoothing:{...smoothed.smoothing,topologyReference:'selected-graph'},pathSelection:{...smoothed.selection}},coordinateSystem:{origin:'top-left',units:'px',space:'original-image',pixelCoordinates:'subpixel smoothed paths; rawPoints retain selected pre-smoothing pixel-center geometry'},roi:{x:roi.x*sx,y:roi.y*sy,width:roi.width*sx,height:roi.height*sy},quality:{reviewRequired:true,pathTopologySimplified:smoothed.selection.mode==='main',physicalConnectivityVerified:false,groundTruthAccuracyValidated:false,includesInferredConnections:includeInference&&smoothed.edges.some(e=>e.inferredSegments.some(Boolean)),depthType:'relative-depression-potential',metricDepth:false,calibratedConfidence:false,widthEstimate:'two-pass chamfer distance; pixel approximation',notes:['Surface recovery uses multiscale grayscale closing, paired shoulders and directional continuity. Its appearance-based segmentation does not verify physical cavities.','Relative relief is derived from photometric contrast and multiscale Hessian valleys. It is not reconstructed physical depth.','Inferred links are image-supported hypotheses, not verified physical connections.','Bridge evidence scores are heuristics, not probabilities. Pixel evidence metrics use processing-image coordinates.','Manual edits preserve or remove inference provenance; erasing does not trigger new automatic reconstruction.']},stats:{...result.stats,...graphStats(smoothed),rawSegments:result.graph.edges.length,rawComponents:result.stats.components,area:result.stats.area*sx*sy,lengthPx:scaledLength(smoothed),rawLengthPx:scaledLength(result.graph)},inferredConnections:bridges,nodes:smoothed.nodes.map(n=>({...n,x:round(n.x*sx),y:round(n.y*sy),clusterPixels:n.clusterPixels.map(map)})),edges:smoothed.edges.map(e=>({...e,provenance:e.provenance??'direct-or-manually-edited',points:e.points.map(map),rawPoints:e.rawPoints.map(map),rawLengthPx:round(scaledLength({edges:[{points:e.rawPoints}]})),lengthPx:round(e.points.slice(1).reduce((sum,p,i)=>sum+Math.hypot((p[0]-e.points[i][0])*sx,(p[1]-e.points[i][1])*sy),0)),meanWidthPx:round(e.meanWidthPx*(sx+sy)/2)}))};
}
